class Solution { fun minDifference(nums:IntArray,queries:Array<IntArray>):IntArray{val prefix=Array(nums.size+1){IntArray(101)};for(i in nums.indices){prefix[i].copyInto(prefix[i+1]);prefix[i+1][nums[i]]++};return IntArray(queries.size){q->var previous=-1;var best=101;val left=queries[q][0];val right=queries[q][1]+1;for(value in 1..100)if(prefix[right][value]>prefix[left][value]){if(previous!=-1)best=minOf(best,value-previous);previous=value};if(best==101)-1 else best}} }
